        "OldStatus" text NOT NULL,
        "NewStatus" text NOT NULL,
        "ChangedByUserId" integer NOT NULL,
        "ChangedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_StatusHistories" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_StatusHistories_Patients_PatientId" FOREIGN KEY ("PatientId") REFERENCES "Patients" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_StatusHistories_Users_ChangedByUserId" FOREIGN KEY ("ChangedByUserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

